import{_ as r,c as o,o as e,a7 as a}from"./chunks/framework.DPTpzYjp.js";const i="/ruidu-docs/images/orbitcontrol/user-guide/devices-page-list.png",s="/ruidu-docs/images/orbitcontrol/user-guide/devices-panel-control.png",d="/ruidu-docs/images/orbitcontrol/user-guide/devices-dialog-mission-selector.png",l="/ruidu-docs/images/orbitcontrol/user-guide/devices-panel-joystick.png",n="/ruidu-docs/images/orbitcontrol/user-guide/devices-dialog-lease-preempt.png",c="/ruidu-docs/images/orbitcontrol/user-guide/devices-flow-initial-pose.gif",g="/ruidu-docs/images/orbitcontrol/user-guide/devices-panel-fpv.png",p="/ruidu-docs/images/orbitcontrol/user-guide/devices-panel-alarm.png",u="/ruidu-docs/images/orbitcontrol/user-guide/devices-panel-alert.png",x=JSON.parse('{"title":"设备控制","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/live-control.md","filePath":"orbitcontrol/user-guide/live-control.md"}'),h={name:"orbitcontrol/user-guide/live-control.md"};function m(b,t,_,f,P,q){return e(),o("div",null,t[0]||(t[0]=[a('<h1 id="设备控制" tabindex="-1">设备控制 <a class="header-anchor" href="#设备控制" aria-label="Permalink to &quot;设备控制&quot;">​</a></h1><p>「设备控制」是平台的实况主页面：左侧选择设备，右侧以地图为底展开操控。选中设备后，可以进行初始定位、点选导航、执行任务、手动遥控等操作。</p><p><img src="'+i+'" alt=""></p><h2 id="设备列表" tabindex="-1">设备列表 <a class="header-anchor" href="#设备列表" aria-label="Permalink to &quot;设备列表&quot;">​</a></h2><p>左侧设备列表展示所有<strong>已注册且已分配站点</strong>的设备，支持按名称搜索和按站点筛选。</p><ul><li>列表卡片显示：在线状态指示灯、设备名称、所属站点、最后更新时间</li><li><strong>点击设备</strong>选中并展开实时状态：电量、卫星数（含 RTK 状态）、经纬度、当前速度</li><li><strong>再次点击</strong>取消选中</li><li>选中后卡片右上角出现设备类型切换按钮，可在「主设备」和「车载无人机」等类型间切换查看</li></ul><p>选中设备后，地图自动加载该设备所属站点的地图；站点没有地图时显示世界地图。站点有多张地图时，通过地图控件中的选择器切换。</p><h2 id="控制模式" tabindex="-1">控制模式 <a class="header-anchor" href="#控制模式" aria-label="Permalink to &quot;控制模式&quot;">​</a></h2><p>地图底部中央是控制面板，提供四种模式。再次点击当前模式按钮即回到<strong>安全待命</strong>（设备停止一切当前行为）。</p><p><img src="'+s+'" alt="" class="w-2/3"></p><table tabindex="0"><thead><tr><th>按钮</th><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><strong>前往位置</strong></td><td>guided</td><td>在地图上点选目标点，设备自动导航前往</td></tr><tr><td><strong>执行任务</strong></td><td>auto</td><td>弹出任务选择框，选择任务后执行</td></tr><tr><td><strong>手动操作</strong></td><td>manual_input</td><td>显示虚拟摇杆，直接遥控设备</td></tr><tr><td><strong>返航</strong></td><td>—</td><td>触发设备自动返航（功能随设备端协议支持逐步开放）</td></tr></tbody></table><h3 id="点选导航-前往位置" tabindex="-1">点选导航（前往位置） <a class="header-anchor" href="#点选导航-前往位置" aria-label="Permalink to &quot;点选导航（前往位置）&quot;">​</a></h3><p>点击「前往位置」进入选点状态：</p><ol><li>在地图上<strong>按下</strong>确定位置，<strong>拖拽</strong>调整朝向，松开完成选取</li><li>确认后下发导航指令，底部出现进度指示</li><li>导航结束设备停留在原地，可继续点选下一个目标</li></ol><p>选点同样适用于路网：点击地图上的路网节点，设备直接前往该节点位置。</p><h3 id="执行任务" tabindex="-1">执行任务 <a class="header-anchor" href="#执行任务" aria-label="Permalink to &quot;执行任务&quot;">​</a></h3><p>点击「执行任务」弹出任务选择对话框，列出当前站点的任务，可搜索，每条任务显示结束动作与预计执行时间。</p><p><img src="'+d+'" alt="" class="w-2/3"></p><p>选择任务后开始执行，底部中央显示<strong>任务进度条</strong>，包含任务名称、进度和三个操作：</p><ul><li><strong>暂停 / 继续</strong>：暂停当前任务，或继续执行</li><li><strong>取消</strong>：退出任务模式，设备停止（回到安全待命）</li></ul><h3 id="手动操作" tabindex="-1">手动操作 <a class="header-anchor" href="#手动操作" aria-label="Permalink to &quot;手动操作&quot;">​</a></h3><p>点击「手动操作」，地图右下角出现虚拟摇杆面板：</p><p><img src="'+l+'" alt="" class="w-1/4"></p><ul><li>点击摇杆<strong>扇区</strong>控制设备进退转向，点击<strong>中心</strong>立即停止</li><li>也支持键盘：<code>W</code>/<code>S</code>/<code>A</code>/<code>D</code> 或方向键控制，<code>空格</code> 急停</li><li>退出手动模式时平台自动下发停止指令，确保设备停稳</li></ul><h2 id="控制权-占用与抢占" tabindex="-1">控制权（占用与抢占） <a class="header-anchor" href="#控制权-占用与抢占" aria-label="Permalink to &quot;控制权（占用与抢占）&quot;">​</a></h2><p>同一设备同一时间只允许一个客户端操控。当你尝试操控正被他人控制的设备时：</p><ul><li>控制面板显示「正由 ××× 控制」，操控按钮被禁用</li><li>若你有抢占权限，可点击「<strong>强制获取</strong>」夺取控制权，对方收到提示后失去控制</li></ul><p><img src="'+n+'" alt="" class="w-2/3"></p><h2 id="初始定位" tabindex="-1">初始定位 <a class="header-anchor" href="#初始定位" aria-label="Permalink to &quot;初始定位&quot;">​</a></h2><p>设备开始工作前，需要先在地图上确定自己的位置。地图左下角提供两个定位按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><strong>初始化设备位置</strong></td><td>点选定位：在地图上按下确定位置、拖拽确定朝向</td></tr><tr><td><strong>GPS 定位</strong></td><td>使用 GPS 坐标自动完成初始定位，需要设备达到 <strong>RTK 固定解</strong> 精度后才可用</td></tr></tbody></table><p><img src="'+c+'" alt="点选定位操作演示"></p><h2 id="fpv-面板" tabindex="-1">FPV 面板 <a class="header-anchor" href="#fpv-面板" aria-label="Permalink to &quot;FPV 面板&quot;">​</a></h2><p>选中设备后，地图右上角显示 FPV（第一视角）面板，实时观看设备摄像头画面。</p><p><img src="'+g+'" alt="" class="w-1/2"></p><ul><li><strong>负载控制</strong>：展开云台/负载控制面板</li><li><strong>全屏显示</strong>：放大 FPV 画面，专注视频操控</li><li><strong>隐藏面板</strong>：暂时收起 FPV</li></ul><h2 id="警报与告警" tabindex="-1">警报与告警 <a class="header-anchor" href="#警报与告警" aria-label="Permalink to &quot;警报与告警&quot;">​</a></h2><p>地图左上角常驻两个面板，点击展开、互斥显示：</p><table tabindex="0"><thead><tr><th>面板</th><th>范围</th><th>内容</th></tr></thead><tbody><tr><td><strong>警报</strong></td><td>场所级</td><td>当前站点的活跃警报，如周界入侵</td></tr><tr><td><strong>告警</strong></td><td>设备级</td><td>选中设备的活跃告警，如电量低、部件异常</td></tr></tbody></table><p><img src="'+p+'" alt="" class="w-1/2"></p><p><img src="'+u+'" alt="" class="w-1/2"></p>',41)]))}const k=r(h,[["render",m]]);export{x as __pageData,k as default};
